def words_in_sentence(sentence):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    if ' = ' in sentence:
        words = sentence.split(' = ')
    else:
        words = sentence.split

    filtered_words = []
    for word in words:
        if is_prime(len(word)):
            filtered_words.append(word)

    return ' '.join(filtered_words)
