def get_max_triples(n):
    # Create an array a
    a = [i * i - i + 1 for i in range(n)]

    # Initialize the number of triples
    count = 0

    # Iterate over all array elements
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                # Check if the sum of a triple is a multiple of 3
                if a[i] + a[j] + a[k] % 3 == 0:
                    count += 1

    return count
