    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5
    """
    if n <= 1:
        return y
    for i in range(2, int):
        if n % i == 0:
            return y
    return x
