    for op in operator[1:]:
        if op == '+':
            result += operand[1]
        elif op == '-':
            result -= operand[1]
        elif op == '*':
            result *= operand[1]
        elif op == '//':
            result //= operand[1]
        elif op == '**':
            result ** operand[1]
    return result
